import { useShellStore } from '@/app/store/shellStore'
import { Menu, Search, Bell } from 'lucide-react'
import { useNavigate } from 'react-router-dom'
import { useNotifications } from '@/app/providers/NotificationProvider'
import { useAuth } from '@/app/providers/AuthProvider'
import { TenantSwitcher } from './TenantSwitcher'

type Props = {
  title?: string
  subtitle?: string
  actions?: React.ReactNode
}

export function PageHeader({ title, subtitle, actions }: Props) {
  const { setLeftPanelOpen, leftPanelOpen } = useShellStore()
  const { unreadCount } = useNotifications()
  const { user, signOut } = useAuth()
  const navigate = useNavigate()

  return (
    <header className="flex items-center justify-between px-4 py-3 border-b border-border bg-surface/80 backdrop-blur-sm shrink-0">
      <div className="flex items-center gap-3">
        <button
          onClick={() => setLeftPanelOpen(!leftPanelOpen)}
          className="p-1.5 rounded-lg hover:bg-muted transition-colors"
        >
          <Menu size={18} className="text-muted-foreground" />
        </button>
        <div>
          {title && <h1 className="font-semibold text-sm">{title}</h1>}
          {subtitle && <p className="text-xs text-muted-foreground">{subtitle}</p>}
        </div>
      </div>

      <div className="flex items-center gap-2">
        <TenantSwitcher />
        {actions}
        <button
          onClick={() => navigate('/app/search')}
          className="p-1.5 rounded-lg hover:bg-muted transition-colors"
        >
          <Search size={16} className="text-muted-foreground" />
        </button>
        <button className="relative p-1.5 rounded-lg hover:bg-muted transition-colors">
          <Bell size={16} className="text-muted-foreground" />
          {unreadCount > 0 && (
            <span className="absolute top-0.5 right-0.5 h-2 w-2 rounded-full bg-accent" />
          )}
        </button>
        <button
          onClick={() => navigate('/app/profile')}
          className="h-7 w-7 rounded-full bg-accent/20 flex items-center justify-center text-xs font-medium text-accent"
        >
          {user?.displayName?.charAt(0).toUpperCase() ?? 'U'}
        </button>
        <button
          onClick={signOut}
          className="text-xs text-muted-foreground hover:text-foreground px-2 py-1 rounded hover:bg-muted"
        >
          Out
        </button>
      </div>
    </header>
  )
}
